  function categoryIndex(key){let hash=0;for(const c of String(key||''))hash=(Math.imul(hash,31)+c.charCodeAt(0))|0;return (hash>>>0)%6;}
  let colors=Theme.palette(document.documentElement.dataset.theme).chartColors;
