    const statusButton=(t,r)=>{const p=cell(t,r);return p?`<button class="matrix-button ${p.status}" data-action="progress" data-task="${t.id}" data-role="${r.id}" title="${esc(p.source||'手工维护')} / ${p.completed}/${p.target}">${p.status==='completed'?'✓':p.status==='skipped'?'—':p.status==='unknown'?'?':p.completed?'◐':'○'} ${['preparing1','preparing2','skipped','unknown'].includes(p.status)?statusLabel(p.status)+' ':''}${p.completed}/${p.target}${p.completionOnly?' / 待补':p.actualCompleted?' / 实测':''}</button>`:'<span class="muted">—</span>';};
