    const preview=()=>{const selected=form.querySelectorAll('[name="roles"]:checked').length,outputs=[...form.querySelectorAll('[name="out_name"]')].filter(x=>x.value.trim()).length;feedback.textContent=`已确认 ${selected} 个角色 / 已填写 ${outputs} 种产物。${!selected?'请在适用角色中确认配方资格。':''}${!outputs?'请至少填写一种产物。':''}保存后按同区服有效材料报价计算利润；缺价会保留未知。`;};
    bar.addEventListener('click',e=>{const b=e.target.closest('[data-recipe-step]');if(b)show(Number(b.dataset.recipeStep));});nav.addEventListener('click',e=>{const b=e.target.closest('[data-recipe-move]');if(!b)return;if(Number(b.dataset.recipeMove)>0){const invalid=panels[step].querySelector(':invalid');if(invalid){invalid.reportValidity();return;}}show(step+Number(b.dataset.recipeMove));});
    form.addEventListener('invalid',e=>{const panel=e.target.closest('.recipe-step');if(panel)show(Number(panel.dataset.step));},true);form.addEventListener('input',preview);form.addEventListener('change',preview);show(0);preview();
