  const pluginCache=new Map();let pluginOwner='',pluginSearch='',pluginPage=0,pluginError='';
  function pluginArchive(){return state.sourceArchives?.filter(x=>x.format==='mingyi-sqlite-v1').sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt.localeCompare(a.updatedAt))[0];}
  async function loadPluginSnapshot(){
    const a=pluginArchive();if(!a||pluginCache.has(a.id))return;
    try{if(typeof JSZip==='undefined')await globalThis.WorkbenchBoot?.loadModule('zip');const zip=await JSZip.loadAsync(a.plugin.zipBase64,{base64:true}),entry=zip.file('snapshot.json');if(!entry)throw new Error('缺少快照数据');const p=JSON.parse(await entry.async('string'));if(p.schema!==1||!Array.isArray(p.roles)||!Array.isArray(p.bags))throw new Error('快照格式不支持');pluginCache.set(a.id,p);pluginError='';}
    catch(e){pluginError=e.message;}
    if(ui.page==='assets'&&ui.assetTab==='plugin')render();
  }
  function pluginSnapshotPanel(){
    const a=pluginArchive();if(!a)return empty('尚未同步插件快照','导入已核对的茗伊工作台 JSON 后，在此查看背包、仓库及副本首领。');
    const p=pluginCache.get(a.id);if(!p){if(!pluginError)void loadPluginSnapshot();return notice(pluginError?'快照读取失败：'+pluginError:'正在读取插件快照…');}
    const ids=new Set(activeRoles().map(r=>r.id)),roleMap=a.plugin.roleMap,ownerAllowed=o=>roleMap[o.ownerkey]?ids.has(roleMap[o.ownerkey]):!ui.role&&!ui.group;
    const owners=p.bagOwners.filter(ownerAllowed),selected=owners.some(o=>o.ownerkey===pluginOwner)?pluginOwner:'',query=pluginSearch.trim().toLowerCase();
    const rows=p.bags.filter(b=>owners.some(o=>o.ownerkey===b[0])&&(!selected||b[0]===selected)&&(!query||b[6].toLowerCase().includes(query)||String(b[4]).includes(query)));
    const pages=Math.max(1,Math.ceil(rows.length/60));pluginPage=Math.min(pluginPage,pages-1);
    const roleName=guid=>state.roles.find(r=>r.id===roleMap[guid])?.name||owners.find(o=>o.ownerkey===guid)?.ownername||guid;
    const location=b=>b[1]<200?'装备栏（不计背包库存）':roleMap[b[0]]?(b[8]>0?'角色仓库':'角色背包'):'帮会仓库（独立）';
    const selectedRoles=p.roles.filter(r=>ids.has(roleMap[r.guid])&&(!selected||r.guid===selected));
    const cds=selectedRoles.flatMap(r=>[...new Set([...Object.keys(r.copies),...Object.keys(r.bosses)])].map(id=>{const m=p.mapCatalog[id],bosses=r.bosses[id];return `<tr><td>${esc(roleName(r.guid))}</td><td>${esc(m?.name||'地图 '+id)}<small>${esc(m?.mode||'难度待核对')} / 地图 ${esc(id)}</small></td><td>${bosses?bosses.map((v,i)=>`${i+1}${v?'✓':'○'}`).join(' '):'未采集首领'}<small>${bosses?bosses.every(Boolean)?'已全通':bosses.some(Boolean)?'部分首领已完成':'未击败首领':'仅有副本实例记录'}</small></td><td>${esc(M.dateKey(new Date(r.collectedAt)))}<small>${esc(new Date(r.collectedAt).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai'}))}</small></td></tr>`;}));
    return notice(`来源：${a.date} 茗伊采集快照。角色资源 / 日常任务加密文件尚未解码；背包持有量不生成收入或可售材料。日期为采集时间，装备栏与帮会仓库单独标记。`)+`<section class="card pad mb"><h2>茗伊角色与资产快照</h2><p class="panel-sub">${a.counts.roles} 个角色 / ${a.counts.occupiedEquipment} 件非空装备槽位（含扩展槽位） / ${a.counts.occupiedBagPositions} 个非空物品位置 / ${a.counts.cdUpdates} 条全通 CD 补入</p><div class="filter-row"><label class="field"><span>快照角色 / 仓库</span><select id="plugin-owner"><option value="">全部角色及独立仓库</option>${owners.map(o=>`<option value="${esc(o.ownerkey)}" ${selected===o.ownerkey?'selected':''}>${esc(roleName(o.ownerkey))}</option>`).join('')}</select></label><label class="field"><span>搜索物品名称 / 表 ID</span><input id="plugin-search" value="${esc(pluginSearch)}" placeholder="输入后按回车"></label></div>${table(['角色','插件原名 / 区服','采集装分','采集时间（北京）'],selectedRoles.map(r=>`<tr><td>${esc(roleName(r.guid))}</td><td>${esc(r.name)}<small>${esc(r.server)}</small></td><td>${num(r.equip_score)}</td><td>${esc(new Date(r.collectedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))}</td></tr>`))}</section><section class="card mb">${head('背包、仓库与装备栏物品',`${rows.length} 个匹配位置 / 第 ${pluginPage+1} / ${pages} 页；各位置按源数据单独列出`)}${table(['归属 / 位置','物品 / 表 ID','背包 / 装备数量','仓库数量','采集日期'],rows.slice(pluginPage*60,(pluginPage+1)*60).map(b=>`<tr><td>${esc(roleName(b[0]))}<small>${location(b)} / ${b[1]}:${b[2]}</small></td><td>${esc(b[6])}<small>${b[3]}:${b[4]}:${b[5]}</small></td><td>${num(b[7])}</td><td>${num(b[8])}</td><td>${M.dateKey(new Date(b[9]*1000))}</td></tr>`))}<div class="pad">${button('上一页','plugin-prev','small',pluginPage===0?'disabled':'')}${button('下一页','plugin-next','small',pluginPage===pages-1?'disabled':'')}</div></section><section class="card">${head('副本首领采集快照','按原地图与难度分别保存；未全通快照不覆盖手工完成或实测。')}${table(['角色','副本 / 难度','首领进度','采集时间（北京）'],cds)}</section>`;
  }
  function workspaceBalancePanel(){const rows=(state.balanceSnapshots||[]).filter(x=>x.scope==='workspace'||!x.roleId);return `<section class="card mt">${head('历史工作空间余额快照','源文件的总级存量余额；变化不计收入，不分配给角色')}${rows.length?table(['日期','金币余额','来源'],rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${x.date}</td><td>${num(x.gold)} G</td><td>${esc(x.source||'导入')}</td></tr>`)):empty('暂无总级余额快照')}</section>`;}
  function wagePanel(){const rows=state.records.filter(r=>r.date>=ui.start&&r.date<=ui.end&&(!ui.taskFilter||r.taskId===ui.taskFilter)&&M.inScope(state,r,scope()));return notice('已到账固定金币计入原执行收益；后续到账按到账日期单独计入实测。应收未付不计收入。历史金币总额无法自动识别工资，登记前核对是否已包含材料出售。')+`<section class="card mt">${head('工资应收与到账','执行日期筛选；每条执行保留本次及后续到账明细')}${rows.length?table(['执行','应收工资','累计到账','未付工资','操作'],rows.map(r=>{const w=Daily.wage(state,r);return `<tr><td>${r.date} / ${esc(r.taskName)}<small>${r.incomeKind==='salary'?'工资 / 固定金币':'历史金币总额 / 待核对'} / ${r.batches} 批</small></td><td>${w.expected==null?'待确认':num(w.expected)+' G'}<small>${w.expected==null?'应收未知':w.unpaid===0?'已到账':w.paid>0?'部分到账':'待到账'}</small></td><td>${num(w.paid)} G<small>执行 ${num(r.gold)} + 后续 ${num(w.paid-r.gold)}</small>${w.receipts.map(e=>`<small>${e.date} +${num(e.gold)} / ${esc(e.eventKey)}</small>`).join('')}</td><td>${w.unpaid==null?'待确认':num(w.unpaid)+' G'}</td><td>${button('登记应收','wage-claim','small',`data-id="${r.id}"`)}${button('登记到账','wage-receipt','small',`data-id="${r.id}"`)}${button('登记材料','new-material','small',`data-record="${r.id}"`)}</td></tr>`;})):empty('暂无执行记录','先记录实际执行，再登记该次工资。')}</section>`;}
  function currentMaterial(m){const v=Daily.inventory(state,m),q=ROI.materialQuote(state,m,today);return {...v,quote:q,estimate:m.tradable!==false&&q?v.left*q.unitGold:null};}
  function materialPanel(){const rows=(state.materials||[]).filter(m=>(!ui.role||m.roleId===ui.role)&&(!ui.group||m.roleId&&state.accounts.find(a=>a.id===state.roles.find(r=>r.id===m.roleId)?.accountId)?.group===ui.group)),known=rows.filter(m=>currentMaterial(m).estimate!=null),estimate=known.reduce((n,m)=>n+currentMaterial(m).estimate,0);return notice(`未售材料参考估值 ${num(estimate)} G；${rows.length-known.length} 项价格未知或不可交易。估值不进入实测收入与人民币现金流；出售按实际成交净金币入账。`)+`<section class="card mt">${head('材料库存与出售','报价带日期；材料掉落不再次计入已到账工资',button('登记材料','new-material','small'))}${rows.length?table(['材料 / 来源','归属','获得 / 剩余','未售估值','已售净金币','操作'],rows.map(m=>{const v=currentMaterial(m);return `<tr><td>${esc(m.name)}<small>${m.date} / ${esc(m.source||'手工')}</small></td><td>${esc(state.roles.find(r=>r.id===m.roleId)?.name||'整队 / 未分配')}</td><td>${num(m.quantity,2)} / ${num(v.left,2)}<small>${v.left===0?'售完':v.sold>0?'部分售出':'持有'}</small><small>${m.tradable===false?'不可交易':'可交易'}</small></td><td>${v.estimate==null?'待估值':num(v.estimate,2)+' G'}<small>${v.quote?quoteSource(v.quote):'报价日期 / 来源待补'}</small></td><td>${num(v.realized,2)} G${v.sales.map(e=>`<small>${e.date} ${num(e.quantity,2)} 件 / ${esc(e.eventKey)}</small>`).join('')}</td><td>${button('更新报价','material-price','small',`data-id="${m.id}"`)}${v.left>0&&m.tradable!==false?button('登记出售','material-sale','small',`data-id="${m.id}"`):'—'}</td></tr>`;})):empty('暂无材料库存','通过执行分账或此页登记真实掉落。')}</section>`;}
  function wageClaimForm(id){const r=state.records.find(r=>r.id===id),w=Daily.wage(state,r);modal('登记应收工资',`${fnum('expected','本次执行应收工资总额（G）',w.expected??w.paid)}<p class="panel-sub">累计到账 ${num(w.paid)} G；应收未付只作对账，不生成收入。</p>`,fd=>commit(()=>{state.wageClaims??=[];const c=state.wageClaims.find(c=>c.recordId===id),value={id:c?.id||M.id('wage'),recordId:id,expectedGold:M.number(fd.get('expected'),'应收工资'),updatedAt:new Date().toISOString()};if(c)Object.assign(c,value);else state.wageClaims.push(value);},'应收工资已保存'));}
  function receiptForm(id){const r=state.records.find(r=>r.id===id);modal('登记后续工资到账',`<div class="form-grid">${field('date','到账日期',today,'date','','required')}${fnum('gold','本次新到账工资（G）',0)}${select('roleId','金币归属',[['','整队 / 未分配'],...r.roleIds.map(id=>[id,state.roles.find(r=>r.id===id)?.name])],'')}${field('eventKey','到账凭据编号','','text','同一事件使用同一编号，重复编号拒绝保存。','required')}${field('note','到账依据 / 备注','','text')}<p class="panel-sub full">只登记尚未计入原执行金币的新到账；有明确所属角色时同步一条关联金币流水，实测收益仍只计一次。</p></div>`,fd=>commit(()=>Daily.receipt(state,{id:M.id('receipt'),recordId:id,date:fd.get('date'),gold:M.number(fd.get('gold'),'到账工资',{min:.000001}),roleId:fd.get('roleId')||null,eventKey:fd.get('eventKey').trim(),note:fd.get('note')}),'工资到账已保存'));}
  function materialForm(recordId=null){const r=state.records.find(r=>r.id===recordId),roles=r?state.roles.filter(x=>r.roleIds.includes(x.id)):state.roles;modal('登记材料库存',`<div class="form-grid">${field('name','材料名称','','text','','required')}${field('itemId','物品 ID（可留空）','')}${field('server','材料区服',state.roles.find(x=>x.id===ui.role)?.server||'','text','未知留空；明确归属角色时可采用该角色区服。')}${fnum('quantity','本次获得数量',1,'','min="0.000001" step="any" required')}${field('date','获得日期',r?.date||today,'date','','required')}${select('roleId','库存归属',[['','整队 / 未分配'],...roles.map(r=>[r.id,r.name])],'')}${select('tradable','交易属性',[['true','可交易'],['false','不可交易']],'true')}${field('unitPrice','参考单价（G，可留空）','','number','','min="0" step="any"')}${field('priceDate','报价日期',today,'date')}${field('priceSource','参考价来源','手工报价','text')}${field('source','来源 / 掉落依据',r?.taskName||'手工','text','','required')}<p class="panel-sub full">获得库存不生成金币收入；与执行关联时，后续出售归入该任务。未知价格保留为空。</p></div>`,fd=>commit(()=>{state.materials??=[];state.materials.push({id:M.id('material'),recordId:r?.id||null,roleId:fd.get('roleId')||null,name:fd.get('name').trim(),itemId:fd.get('itemId').trim(),server:fd.get('server').trim()||state.roles.find(r=>r.id===fd.get('roleId'))?.server||'',pricingMode:'manual',priceSource:fd.get('priceSource').trim(),priceValidForHours:72,quantity:M.number(fd.get('quantity'),'材料数量',{min:.000001}),date:fd.get('date'),tradable:fd.get('tradable')==='true',unitPrice:fd.get('unitPrice')===''?null:M.number(fd.get('unitPrice'),'参考价'),priceDate:fd.get('unitPrice')===''?null:fd.get('priceDate'),source:fd.get('source')});},'材料库存已保存，未计入收入'));}
