    const source=state.plans.find(p=>p.id===$('#raid-reuse-source').value),indices=[...document.querySelectorAll('[name="raid-reuse-team"]:checked')].map(x=>Number(x.value)),ids=selectedTeamIds(state.tasks.find(t=>t.id===taskId));
