  function parseCSV(text){
    const operational=Importer.operationsCSV(text,state);if(operational)return operational;
    const rows=[];let row=[],value='',quoted=false;
    text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(value);value='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(v=>v.trim()))rows.push(row);row=[];value='';}else value+=c;}
    if(quoted)throw new Error('CSV 引号未闭合');row.push(value);if(row.some(v=>v.trim()))rows.push(row);if(rows.length<2)throw new Error('CSV 需要表头与至少一行角色数据');
    const headers=rows.shift().map(h=>h.trim());for(const h of ['account_id','account_name','role_id','role_name'])if(!headers.includes(h))throw new Error('CSV 缺少字段 '+h);
    const s=M.blank(),time=new Date().toISOString();s.config={...state.config};
    for(const values of rows){const r=Object.fromEntries(headers.map((h,i)=>[h,(values[i]||'').trim()]));if(!s.accounts.some(a=>a.id===r.account_id))s.accounts.push({id:r.account_id,name:r.account_name,group:r.group||'',balance:r.balance?M.number(r.balance,'点卡余额'):0,balanceExpiry:null,...(r.region?{region:r.region}:{}),...(r.billing_type?{billingType:r.billing_type}:{}),...(r.monthly_expires_at?{monthlyExpiresAt:r.monthly_expires_at}:{}),...(r.tongbao?{tongbao:M.number(r.tongbao,'通宝')}:{}),...(r.points?{points:M.number(r.points,'积分')}:{}),enabled:true,updatedAt:time});const optional=k=>r[k]?M.number(r[k],k):null;s.roles.push({id:r.role_id,name:r.role_name,accountId:r.account_id,server:r.server||'',school:r.school||'',stance:r.stance||'',duty:r.duty||'unknown',level:optional('level'),score:optional('score'),openingGold:optional('opening_gold'),observedGold:optional('observed_gold'),camp:r.camp||'unknown',...Object.fromEntries(['energy','energyCap','weeklyEnergy','contribution','chivalry','prestige','achievement','stage','huashang','homeSeason'].map(k=>[k,optional(k)])),resourceUpdatedAt:r.resource_date?new Date(r.resource_date+'T12:00:00+08:00').toISOString():null,...(headers.includes('reference_dps')?{referenceDps:optional('reference_dps')}:{}),...(headers.includes('gongzhan_buff')?{gongzhanBuff:parseGongzhan(r.gongzhan_buff)}:{}),enabled:true,tags:r.tags||'',companion:r.companion||'',updatedAt:time,csvFields:r});}
    return M.validateState(s);
  }
