    if(files.length>12){status.dataset.tone='warning';status.textContent='每批最多 12 张截图，请分批导入';return;}
    if(files.reduce((n,f)=>n+f.size,0)>60*1024*1024){status.dataset.tone='warning';status.textContent='截图总大小不可超过 60 MB，请分批导入';return;}
